def pluck(arr):

    if not arr or all(val % 2 == 1 for val in arr):

        return []

    min_even = min((val for val in arr if val % 2 == 0), default=None)

    if min_even is None:

        return []

    min_even_index = arr.index(min_even)

    return [min_even, min_even_index]

