def is_multiply_prime(a):
    """Check if the given number is the multiplication of exactly three prime numbers.

    Args:
        a (int): The number to check, which is less than 100.

    Returns:
        bool: True if the number is the multiplication of three prime numbers, False otherwise.

    Examples:
        is_multiply_prime(30) == True
        30 = 2 * 3 * 5
    """

    if a <= 1:
        return False

    # Sieve of Eratosthenes to find all prime numbers up to 'a'
    is_prime = [True] * (a + 1)
    for i in range(2, a + 1):
        if is_prime[i]:
            for j in range(i * i, a + 1, i):
                is_prime[j] = False

    # Count the number of prime factors
    prime_factors_count = 0
    for i in range(2, a + 1):
        if is_prime[i]:
            while a % i == 0:
                a //= i
                prime_factors_count += 1
                if prime_factors_count > 3:
                    return False

    return prime_factors_count == 3

