def numerical_letter_grade(grades):
    """Convert a list of GPAs to their corresponding letter grades based on the given scale.

    Parameters:
    grades (list of float): A list of GPA scores.

    Returns:
    list of str: A list of letter grades corresponding to the input GPAs.

    Example:
    grade_equation([4.0, 3, 1.7, 2, 3.5]) ==> ['A+', 'B', 'C-', 'C', 'A-']
    """

    def to_letter_grade(score):
        """Convert a single GPA score to its corresponding letter grade."""
        if score == 4.0:
            return "A+"
        elif score > 3.7:
            return "A"
        elif score > 3.3:
            return "A-"
        elif score > 3.0:
            return "B+"
        elif score > 2.7:
            return "B"
        elif score > 2.3:
            return "B-"
        elif score > 2.0:
            return "C+"
        elif score > 1.7:
            return "C"
        elif score > 1.3:
            return "C-"
        elif score > 1.0:
            return "D+"
        elif score > 0.7:
            return "D"
        elif score > 0.0:
            return "D-"
        else:
            return "E"

    return [to_letter_grade(score) for score in grades]
