def histogram(test):
    """Given a string representing space-separated lowercase letters, return a dictionary
    of the letter(s) with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """


    if not test:
        return {}

    letter_count = {}
    for word in test.split(" "):
        if word:
            letter_count[word] = letter_count.get(word, 0) + 1

    max_count = max(letter_count.values())
    most_frequent_letters = {letter: count for letter, count in letter_count.items() if count == max_count}

    return most_frequent_letters

